// modules/boss-defaults.js
// -----------------------------------------------------------------------------
// The Boss Creator's form state. The attack TYPES, their fields and defaults are not listed here:
// they come from Unity's catalog (modules/boss-catalog.js, generated by BossCatalogExporter.cs),
// so an archetype added in C# shows up here with no web edit. This file only builds values from a
// catalog field list and holds the defaults of the parts that are not per-type (body, phases).

/** Body stats — the same fallbacks BossBodyBuilder.cs uses when a key is missing. */
export const BODY_STATS = [
  ['height', 'Altura (u)', 6, 'Alto del dibujo en el mundo.'],
  ['hoverHeight', 'Flota a (u)', 0, 'Separación del suelo (flotantes).'],
  ['health', 'Vida', 2500, ''],
  ['contactDamage', 'Daño por contacto', 12, ''],
  ['arenaHalfWidth', 'Media anchura de arena (u)', 15, 'Hasta dónde se mueve y apunta.'],
  ['arenaHeight', 'Altura de arena (u)', 12, ''],
  ['activationRadius', 'Se activa a (u)', 18, 'Distancia del jugador que empieza el combate.'],
  ['colliderWidth', 'Collider · ancho (× dibujo)', 0.5, ''],
  ['colliderHeight', 'Collider · alto (× dibujo)', 0.8, ''],
];

let _attackSeq = 0;

export function resetAttackIdCounter(start = 0) { _attackSeq = start; }

/** Deep copy of a JSON-ish value. */
export const clone = (v) => (v === undefined ? undefined : JSON.parse(JSON.stringify(v)));

/**
 * Default VALUES for a catalog field list: `{name: default}`, nested objects recursed. Art fields
 * default to '' (= "use the attack's placeholder"), which is what an empty slot means in Unity.
 */
export function defaultsOf(fields = []) {
  const out = {};
  fields.forEach((f) => {
    if (f.type === 'object') out[f.name] = defaultsOf(f.fields);
    else if (f.type === 'art') out[f.name] = '';
    else if (f.type === 'unity') return;
    else out[f.name] = clone(f.default);
  });
  return out;
}

/** Fills `values` with defaults for any field it lacks (a type gained a field since it was saved). */
export function withDefaults(fields = [], values = {}) {
  const out = { ...values };
  fields.forEach((f) => {
    if (f.type === 'unity') return;
    if (f.type === 'object') out[f.name] = withDefaults(f.fields, values[f.name] || {});
    else if (!(f.name in out)) out[f.name] = f.type === 'art' ? '' : clone(f.default);
  });
  return out;
}

export function createAttack(catalog, type, takenIds = []) {
  const taken = new Set(takenIds);
  do { _attackSeq += 1; } while (taken.has(`Ataque${_attackSeq}`));
  const entry = catalog?.attacks.find((a) => a.type === type) || catalog?.attacks[0];
  return {
    id: `Ataque${_attackSeq}`,
    // Field paths edited in the web ('damage', 'projectile.speed'…): always exported, even when put
    // back to the default, so the web's value wins over what the asset had.
    edited: {},
    type: entry ? entry.type : type,
    open: true,
    common: { ...defaultsOf(catalog?.common || []), displayName: '' },
    params: defaultsOf(entry?.params || []),
  };
}

export function createDefaultPhase(index = 0) {
  return {
    displayName: `Fase ${index + 1}`,
    // Phase 0 MUST be 1: BossDefinition.OnValidate forces it.
    startsAtHealth: index === 0 ? 1 : 0.5,
    attacks: [],
    pauseBetweenAttacks: index === 0 ? { x: 0.9, y: 1.5 } : { x: 0.6, y: 1.1 },
    damageScale: index === 0 ? 1 : 1.15,
    damageTakenMultiplier: 1,
    speedScale: index === 0 ? 1 : 1.3,
    accent: '#8ce666ff',
    transitionSeconds: index === 0 ? 0 : 1.8,
    transitionShake: 0.5,
    frenzyBelowHealth: 0,
    frenzySpeedScale: 1.35,
    openingAttack: '',
  };
}

export function createDefaultBody() {
  const body = {
    libraryId: '',
    entryName: '',
    anims: {},        // laneName -> { fps, loop, releaseFrame } (overrides of the lane's own values)
    derived: [],      // { name, from, first, count, fps, loop }
    movement: { type: 'HoverKeepDistance', params: null },
    warnCircle: '',   // library id or '' (= placeholder)
    warnArrow: '',
  };
  BODY_STATS.forEach(([key, , def]) => { body[key] = def; });
  return body;
}

export function createDefaultBossConfig() {
  resetAttackIdCounter();
  return {
    displayName: '',
    title: '',
    description: '',
    body: createDefaultBody(),
    art: {},          // `${libraryId}:${artKind}` -> { worldWidth, colliderScale, faceTravelDirection, tint }
    attacks: [],
    phases: [createDefaultPhase(0)],
  };
}

export function createArtOptions(kind) {
  return { worldWidth: kind === 'warning' ? 2 : 1.5, colliderScale: 0.8, faceTravelDirection: kind === 'projectile', tint: false };
}
